{
  "supports": [
    {
      "claim_id": "A0",
      "rationale": "Paragraph (a) in F000 introduces the prohibition governing the driver ('No driver shall'), which applies to being on duty or operating a commercial motor vehicle while possessing alcohol under paragraph (a)(3) in F003, and the exception for shipments manifested and transported in F004. Thus, the contiguous range F000:F004 establishes the driver as the actor of this duty and qualification.",
      "source_refs": [
        "F000:F004"
      ]
    },
    {
      "claim_id": "A1",
      "rationale": "Paragraph (a) in F000 establishes the duty applying to the driver ('No driver shall'), which extends through paragraph (a)(3) in F003 regarding alcohol possession while on duty, and includes the exception in F005 for alcohol possessed or used by bus passengers. Thus, the contiguous range F000:F005 establishes the driver as the actor of this duty and qualification.",
      "source_refs": [
        "F000:F005"
      ]
    }
  ]
}
